def search(topic, limit=5):
    if not isinstance(topic, str) or not topic.strip() or len(topic) > 200 or (type(limit) is not int) or (not 1 <= limit <= 10):
        raise ValueError('topic must be 1–200 characters and limit 1–10')
    q = topic.casefold().strip()
    matches = []
    for item in ENTRIES:
        hits = [t for t in item['topics'] if t.casefold() in q or q in t.casefold()]
        if not hits:
            continue
        score = max((len(t) for t in hits))
        regions = {'英国政府开放数据目录': ['英国', 'uk', 'britain'], '英国国家统计局 ONS 数据': ['英国', 'uk', 'britain', 'ons'], '爱尔兰与瑞士政府开放数据目录': ['爱尔兰', '瑞士', 'ireland', 'switzerland'], '芬兰政府开放数据目录': ['芬兰', 'finland'], '希腊政府开放数据目录': ['希腊', 'greece'], '澳大利亚昆士兰州开放数据目录': ['昆士兰', '澳大利亚', 'queensland', 'australia']}
        aliases = regions.get(item['name'])
        region_rank = 1 if aliases and any((alias in q for alias in aliases)) else -1 if aliases else 0
        matches.append((score, region_rank, item, hits))
    matches.sort(key=lambda x: (-x[0], -x[1]))
    out = []
    for score, region_rank, item, hits in matches[:limit]:
        cmds = []
        for cmd in item['commands']:
            p = release_runtime.run([sys.executable, str(ROOT / 'research.py'), cmd, '--help'], capture_output=True, text=True, timeout=15)
            cmds.append({'command': cmd, 'registered': p.returncode == 0, 'help': p.stdout.strip() if p.returncode == 0 else None})
        out.append({'name': item['name'], 'matched_aliases': hits, 'scope': item['scope'], 'commands': cmds})
    return {'query': topic, 'matching_entries': len(matches), 'items': out, 'note': '这是人工整理的小规模关键词/同义词索引，不是自动语义路由或全部工具目录；不执行检索，也不检测源站当前可用性。命令注册验证仅代表本机命令存在；时间、地区、单位、授权以实际查询与原始来源为准。无匹配不代表没有相关数据源。'}
